n32","name":"realm royale/binaries/win64/realmeac.exe","is_launcher":false}],"storefront_available":false,"bot_public":true,"bot_require_code_grant":false,"integration_types_config":{"0":{}},"verify_key":"ddaf4497f6b562b43303e528b27e3fa311647c321e435b63535d04dafda4cb3a","flags":0,"flags_new":"0"},"system_requirements":{"1":{"minimum":{"operating_system_version":"Windows 7","cpu":"Intel(R) Core(TM) i5-2320 CPU @ 3.0 GHz (4 CPUs), ~3.0 GHz","gpu":"NVIDIA GeForce GTX 555","ram":6000,"disk":5000,"sound_card":null,"directx":"11","network":null,"notes":"Requires a 64-bit processor and operating system"},"recommended":{"operating_system_version":null,"cpu":null,"gpu":null,"ram":null,"disk":null,"sound_card":null,"directx":null,"network":null,"notes":null}}},"show_age_gate":false,"price":{"amount":0,"currency":"aud","currency_exponent":2},"locales":["pt-BR","pl","es-ES","ru","zh-TW","zh-CN","fr","en-US","de"],"tenant_metadata":{},"created_at":"2025-08-05T20:53:39.133830+00:00","updated_at":"2025-08-05T20:53:39.135755+00:00"},"tagline":"Can you survive the first 100-person fantasy Battle Royale? Choose a class, craft deadly weapons and abilities, and forge your own victory. Unlock the exclusive Sprinkles chicken skin for FREE with Nitro.","flavor_text":"Chickens and donuts. What more could you want?","description":"![](asset://535859924819771393)\n\n**Nitro subscribers get the Discord-exclusive Sprinkles Chicken skin for free!**  Satisfy your sweet tooth with the delicious Sprinkles Chicken!\n\n![](asset://534482236293251072)\n\nExplore a fantasy world in Realm Royale, the Battle Royale sensation. Choose your class, loot fantastic weapons and magical abilities, and work with your squad to win. Stay ahead of the deadly fog by mounting up and moving out. Will you be the last Champion standing?\n\n![](asset://534482238432215040)\n\nCall your friends: It\u2019s time to squad up. Help your team by dropping a Healing Totem, or fire a Flare into the sky to reveal incoming enemies. By working together as a team the crown royale could be yours.\n\n![](asset://537765172261945354)\n\nDiscover powerful abilities scattered across the Realm. Soar through the skies slinging spells while your team deploys deadly turrets and shields. Flank the enemy with the stealthy Ghost Walk, leaving behind a proximity mine for them to discover when it\u2019s too late. Customize your Champion each game with the abilities best suited for the battle at hand.\n\n![](asset://534482237056614413)\n\nGo traditional with shotguns and snipers, or embrace the fantasy with ice staffs, swords, and crossbows. If you want to win, you\u2019ll need to use the Forges scattered across the Realm to craft powerful Runes, epic Gear, or bring back your fallen teammates. But be careful: While you\u2019re crafting, your enemies may attack.\n\n![](asset://534482238977605652)\n\nJourney through the lush jungle of Jaguar\u2019s Claws and the scorched sands of Goblin Gulch. Visit frigid Everfrost and iridescent Fungal Forest. The best part: you don\u2019t have to walk around this massive Realm. Just summon your mount to outrun the fog and ride into your next glorious battle!","staff_notes":{"content":"As someone who prefers to get right into the fight, Realm Royale prioritizes my favorite part of shooter games: shooting things. While some battle royales focus on time-intensive mechanics like looting and building, this game forces you to go out and fight people for the chance of better items, while keeping everything going at a good pace. Spend less time preparing, and more time fighting.","user":null},"carousel_items":[{"asset_id":"535984194581561360"},{"asset_id":"532306234645151776"},{"asset_id":"532306234636763142"},{"asset_id":"532306234695614464"},{"asset_id":"532306234812923904"},{"asset_id":"532304691535675405"}],"child_skus":[{"id":"564916655285600266","type":2,"product_line":null,"dependent_sku_id":null,"application_id":"518088627234930688","manifest_labels":["530470431568822332"],"ac